commits.content:
/* NavBar styles */
.nav {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  width: calc(100% - 40px);
  max-width: 900px;
  padding: 10px 20px;
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 20px;
  backdrop-filter: blur(10px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
}

.nav__inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.nav__links {
  list-style: none;
  display: flex;
  gap: 20px;
  margin: 0;
  padding: 0;
}

.nav__links a {
  text-decoration: none;
  color: #222;
  padding: 6px 10px;
  border-radius: 12px;
  transition: background 0.2s ease;
}

.nav__links a:hover {
  background: rgba(0, 0, 0, 0.05);
}
